def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    def opp_at(i):
        return history[i][1]

    def me_at(i):
        return history[i][0]

    # Quick counts
    opp_c = 0
    opp_d = 0
    for i in range(n):
        if opp_at(i) == 'C':
            opp_c += 1
        else:
            opp_d += 1

    # Always defect / always cooperate detectors
    if n >= 4:
        if opp_d == 0:
            # Pure cooperator: mostly exploit near end, occasionally earlier
            if n >= 94:
                return 'D'
            if n >= 60 and n % 8 == 0:
                return 'D'
            return 'C'
        if opp_c == 0:
            return 'D'

    last_opp = opp_at(n - 1)
    last_me = me_at(n - 1)

    # Current opponent defection streak
    streak_d = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'D':
        streak_d += 1
        i -= 1

    # Current opponent cooperation streak
    streak_c = 0
    i = n - 1
    while i >= 0 and opp_at(i) == 'C':
        streak_c += 1
        i -= 1

    coop_rate = opp_c / n

    # Endgame: last few rounds
    remaining = 100 - n
    if remaining <= 4:
        if coop_rate > 0.6 or streak_c >= 1:
            return 'D'
        return 'D'

    # Heavy defector: pure defense, but try to re-establish if they soften
    if coop_rate < 0.25:
        if streak_c >= 3:
            return 'C'
        return 'D'

    # Strong punisher: if opponent just defected twice in a row, keep defecting
    if streak_d >= 2:
        # If they've been mostly cooperative overall, forgive after punishing
        if coop_rate > 0.7 and streak_d == 2:
            return 'C'
        return 'D'

    # Single defection: retaliate once, with forgiveness if they've been good
    if streak_d == 1:
        if coop_rate > 0.75 and streak_c >= 2:
            return 'C'
        if n >= 3 and opp_at(n - 2) == 'C' and opp_at(n - 3) == 'C':
            if coop_rate > 0.6:
                return 'C'
        return 'D'

    # Opponent cooperating now
    # Mirror current cooperation but occasionally try small exploitation
    # if opponent has been reliably cooperative and hasn't retaliated recently
    if coop_rate > 0.7:
        # Check whether opponent recently retaliated to our defections
        recent_my_d = 0
        start = n - 6
        if start < 0:
            start = 0
        for j in range(start, n):
            if me_at(j) == 'D':
                recent_my_d += 1
        # If we've been defecting and they still cooperate, it's safe to exploit
        if recent_my_d >= 2:
            return 'D'
        # Otherwise mostly cooperate with rare probing
        if n >= 20 and n <= 85 and n % 11 == 0:
            return 'D'
        return 'C'

    # Moderate cooperation opponent: tit-for-tat with forgiveness
    if coop_rate > 0.45:
        if last_me == 'D':
            return 'C'
        # Rarely defect to test
        if n >= 30 and n % 15 == 0:
            return 'D'
        return 'C'

    # Cautious middle-low: defect more, but occasionally cooperate
    if coop_rate > 0.3:
        if streak_c >= 2:
            return 'C'
        if rng.random() < 0.4:
            return 'C'
        return 'D'

    return 'D'
